// HasIncomingMessageIDRef applies the HasEdge predicate on the "incoming_message_id_ref" edge.
func HasIncomingMessageIDRef() predicate.MessageJob {
	return predicate.MessageJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IncomingMessageIDRefTable, IncomingMessageIDRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIncomingMessageIDRefWith applies the HasEdge predicate on the "incoming_message_id_ref" edge with a given conditions (other predicates).
